package com.bank.token;

import java.util.*;
import java.util.logging.*;

public class RangeDemo {
    private static final Logger log = Logger.getLogger("Token");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        TokenService service = new TokenService();
        List<Integer> even = service.evenTokens();
        log.info(() -> "Even tokens routed to express counter: " + even);
    }
}

// ─── Would be in service/TokenService.java ───
class TokenService {
    List<Integer> evenTokens() {
        return java.util.stream.IntStream.range(1, 11)   // 1..10 (11 excluded)
            .filter(n -> n % 2 == 0)                       // keep evens
            .boxed()                                       // IntStream → Stream<Integer>
            .collect(java.util.stream.Collectors.toList());
    }
}
